       });

     for (const { encontroId, teto } of cenarios) {
       const participantes = Array.from(
         { length: teto + 1 },
         (_, i) => `p-teto${String(i + 1).padStart(2, '0')}`,
       );
       for (let i = 0; i < teto; i += 1) {
